// src/components/globe/GlobeContainer.jsx
// Sizing + lazy-load wrapper around GlobeView, the game's map. react-globe.gl needs explicit
// pixel width/height (unlike a flat SVG's viewBox, which scales itself) — a ResizeObserver keeps
// it in sync with its flex-layout container. The three.js-based renderer (~1MB+) is fetched once
// this mounts.
import React, { Suspense, useEffect, useRef, useState } from 'react';
import { lazyWithReload } from '../../utils/lazyWithReload';

const GlobeView = lazyWithReload(() => import('./GlobeView'));

const GlobeContainer = ({
  selectedRegion, onSelectRegion, onAmbiguousTap = null, focusRegionId = null, navigateTarget = null, onViewportChange = null, onSelectTile = null, onSelectArmy = null, lens = 'political'
}) => {
  const containerRef = useRef(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      setSize({ width: Math.round(width), height: Math.round(height) });
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={containerRef} className="relative w-full h-full bg-slate-900">
      <Suspense fallback={
        <div className="w-full h-full flex items-center justify-center text-slate-400 text-sm">
          Loading globe renderer…
        </div>
      }>
        {size.width > 0 && size.height > 0 && (
          <GlobeView
            width={size.width}
            height={size.height}
            selectedRegion={selectedRegion}
            onSelectRegion={onSelectRegion}
            onAmbiguousTap={onAmbiguousTap}
            focusRegionId={focusRegionId}
            navigateTarget={navigateTarget}
            onViewportChange={onViewportChange}
            onSelectTile={onSelectTile}
            onSelectArmy={onSelectArmy}
            lens={lens}
          />
        )}
      </Suspense>
    </div>
  );
};

export default GlobeContainer;
